from pathlib import Path
P=Path(__file__).resolve().parents[1];f=P/'web/showcase-frontier-3d.js';s=f.read_text(encoding='utf-8')
s=s.replace("const block=(x,y,z,w,h,d,mat=stone,group=scene)=>mesh(new THREE.BoxGeometry(w,h,d),mat,x,y,z,group);", "const block=(x,y,z,w,h,d,mat=stone,group=scene)=>{const m=mesh(new THREE.BoxGeometry(w,h,d),mat,x,y,z,group);if(y+h/2<=.03)m.renderOrder=-10;return m;};")
s=s.replace('const at=o.geometry.attributes.position,index=o.geometry.index,mat=o.material;', 'const at=o.geometry.attributes.position,uv=o.geometry.attributes.uv,index=o.geometry.index,mat=o.material;')
s=s.replace('tris.push({v,color:color.getStyle(),z:v.reduce((t,q)=>t+q.z,0)/3,mat});', "const tex=mat.map?.image;const coords=tex&&uv?[0,1,2].map(k=>{const n=index?index.getX(i+k):i+k;return {x:uv.getX(n)*tex.width,y:(1-uv.getY(n))*tex.height}}):null;tris.push({v,color:color.getStyle(),z:v.reduce((t,q)=>t+q.z,0)/3,mat,tex,coords,shade,order:o.renderOrder||0});")
s=s.replace('tris.sort((a,b)=>b.z-a.z);', 'tris.sort((a,b)=>a.order-b.order||b.z-a.z);')
s=s.replace('ctx.fillStyle=t.color;ctx.fill();}', "ctx.fillStyle=t.color;ctx.fill();if(t.tex&&t.coords){const [u,v,w]=t.coords,p=t.v.map(q=>({x:(q.x*.5+.5)*1120,y:(.5-q.y*.5)*630})),det=(v.x-u.x)*(w.y-u.y)-(w.x-u.x)*(v.y-u.y);if(Math.abs(det)>.01){const aa=((p[1].x-p[0].x)*(w.y-u.y)-(p[2].x-p[0].x)*(v.y-u.y))/det,bb=((p[1].y-p[0].y)*(w.y-u.y)-(p[2].y-p[0].y)*(v.y-u.y))/det,cc=((p[2].x-p[0].x)*(v.x-u.x)-(p[1].x-p[0].x)*(w.x-u.x))/det,dd=((p[2].y-p[0].y)*(v.x-u.x)-(p[1].y-p[0].y)*(w.x-u.x))/det;ctx.save();ctx.clip();ctx.transform(aa,bb,cc,dd,p[0].x-aa*u.x-cc*u.y,p[0].y-bb*u.x-dd*u.y);ctx.drawImage(t.tex,0,0);ctx.restore();ctx.save();ctx.fillStyle='rgba(12,32,36,'+(1-t.shade)*.55+')';ctx.fill();ctx.restore();}}}")
f.write_text(s,encoding='utf-8');print('Depth layering and UV texture projection repaired for compatibility renderer.')
